#import <Cocoa/Cocoa.h>
#include "../default_maps.h"
#include <assert.h>
int main(int argc,const char **argv){@autoreleasepool{assert(argc==2);NSURL *source=[NSURL fileURLWithPath:[NSString stringWithUTF8String:argv[1]]];NSURL *target=[NSURL fileURLWithPath:[@"/private/tmp" stringByAppendingPathComponent:NSUUID.UUID.UUIDString] isDirectory:YES];NSFileManager *files=NSFileManager.defaultManager;[files createDirectoryAtURL:target withIntermediateDirectories:YES attributes:nil error:nil];NSURL *custom=[target URLByAppendingPathComponent:@"1.png"];NSData *user=[@"Existing user map" dataUsingEncoding:NSUTF8StringEncoding];[user writeToURL:custom atomically:YES];NSError *error=nil;assert(installDefaultMapFiles(source,target,&error)&&!error);NSUInteger count=0;NSSet *extensions=[NSSet setWithArray:@[@"png",@"jpg",@"jpeg",@"bmp",@"gif",@"tif",@"tiff",@"pgm"]];for(NSString *name in [files contentsOfDirectoryAtPath:source.path error:nil]){if(![extensions containsObject:name.pathExtension.lowercaseString])continue;NSData *expected=[name isEqual:@"1.png"]?user:[NSData dataWithContentsOfURL:[source URLByAppendingPathComponent:name]];assert([[NSData dataWithContentsOfURL:[target URLByAppendingPathComponent:name]]isEqual:expected]);count++;}assert(count>0);assert([files contentsOfDirectoryAtPath:target.path error:nil].count==count);assert(installDefaultMapFiles(source,target,&error));[files removeItemAtURL:target error:nil];printf("Installed %lu bundled maps; all file contents verified and existing user map preserved.\n",(unsigned long)count);}return 0;}
